Here is the commit message:
cache: sifive_ccache: Silence unused variable warning

With W=1 and CONFIG_RISCV_NONSTANDARD_CACHE_OPS=n, GCC warns:

drivers/cache/sifive_ccache.c: In function 'sifive_ccache_init':
drivers/cache/sifive_ccache.c:293:23: warning: variable 'quirks' set but not used [-Wunused-but-set-variable]
  293 |         unsigned long quirks;
      |                       ^~~~~~

This is expected, since QUIRK_NONSTANDARD_CACHE_OPS is the only quirk
still handled in this function.

Fixes: c90847bcbfb6 ("cache: sifive_ccache: Partially convert to a platform driver")
Reported-by: kernel test robot <lkp@intel.com>
Closes: https://lore.kernel.org/oe-kbuild-all/202403311253.Z4NvIBxI-lkp@intel.com/
Signed-off-by: Samuel Holland <samuel.holland@sifive.com>
Signed-off-by: Conor Dooley <conor.dooley@microchip.com>

Here is the root cause:
The root cause of the bug is the declaration of the variable `quirks` in the `sifive_ccache_init` function, which is set but not used in the code. This leads to a compiler warning when the configuration `CONFIG_RISCV_NONSTANDARD_CACHE_OPS` is set to `n`, as the compiler detects that the variable is unnecessary for the current logic of the function.

Here is the patch:

 static int __init sifive_ccache_init(void)
 {
 	struct device_node *np;
 	struct resource res;
 	const struct of_device_id *match;
-	unsigned long quirks;
+	unsigned long quirks __maybe_unused;
 	int rc;

 	np = of_find_matching_node_and_match(NULL, sifive_ccache_ids, &match);
 	if (!np)
 		return -ENODEV;

 	quirks = (uintptr_t)match->data;

 	if (of_address_to_resource(np, 0, &res)) {
 		rc = -ENODEV;
 		goto err_node_put;
 	}

 	ccache_base = ioremap(res.start, resource_size(&res));
 	if (!ccache_base) {
 		rc = -ENOMEM;
 		goto err_node_put;
 	}

 	if (of_property_read_u32(np, "cache-level", &level)) {
 		rc = -ENOENT;
 		goto err_unmap;
 	}

 #ifdef CONFIG_RISCV_NONSTANDARD_CACHE_OPS
 	if (quirks & QUIRK_NONSTANDARD_CACHE_OPS) {
 		riscv_cbom_block_size = SIFIVE_CCACHE_LINE_SIZE;
 		riscv_noncoherent_supported();
 		riscv_noncoherent_register_cache_ops(&ccache_mgmt_ops);
 	}
 #endif

 	ccache_config_read();

 	ccache_cache_ops.get_priv_group = ccache_get_priv_group;
 	riscv_set_cacheinfo_ops(&ccache_cache_ops);

 #ifdef CONFIG_DEBUG_FS
 	setup_sifive_debug();
 #endif

 	rc = platform_driver_register(&sifive_ccache_driver);
 	if (rc)
 		goto err_unmap;

 	of_node_put(np);

 	return 0;

 err_unmap:
 	iounmap(ccache_base);
 err_node_put:
 	of_node_put(np);
 	return rc;
 }



